     if (!res.ok) {
@@ -198,7 +211,12 @@ export function RunLand({ run }: { run: RunDTO }) {
       return;
     }
     setState(res.data.state);
-    setStrategy(res.data.defaultStrategy);
+    // The server's answer fills the gap while the operator has not chosen, and
