+    // before Commit — which is the order this card asks for — and the next
+    // press of Land put every commit on the target instead of one.
+    setDefaultStrategy(res.data.defaultStrategy);
     setResolution(res.data.resolution);
     setReadError(null);
   }, [run.id]);
